    int *suff = (int *)malloc(n * sizeof(int));

    for (int i = 0; i < n; i++) {
        scanf("%d", &h[i]);
    }

    int mx = 0;
    for (int i = n - 1; i >= 0; i--) {
        if (h[i] > mx) mx = h[i];
        suff[i] = mx;
    }

    mx = 0;
    int ans = 0;

    for (int i = 0; i < n; i++) {
        if (h[i] > mx) mx = h[i];

        int waterLevel = mx < suff[i] ? mx : suff[i];

        if (waterLevel > h[i]) {
            ans++;
        }
